<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{SalesInvoice,SalesInvoiceItem,SalesOrder,SalesOrderItem,SalesSetting}; use App\Services\{AuthorizationService,SalesCalculationService,SalesNumberService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SalesInvoiceController { public function index(Request $r){$q=SalesInvoice::where('tenant_id',app(TenantContext::class)->id())->with('customer')->latest();return response()->json(['data'=>$q->paginate(min($r->integer('per_page',25),100))]);} public function store(Request $r,SalesOrder $order,AuthorizationService $a,SalesNumberService $numbers,SalesCalculationService $calc){abort_unless($order->tenant_id===app(TenantContext::class)->id(),404);abort_unless($a->allows($r->user(),$order->tenant_id,'sales.manage',$order->company_id,$order->branch_id),403);$d=$r->validate(['items'=>'required|array|min:1','items.*.sales_order_item_id'=>'required|uuid','items.*.quantity'=>'required|numeric|min:0.000001']);$invoice=DB::transaction(function()use($d,$order,$numbers,$calc){$lines=[];$source=[];foreach($d['items'] as $line){$item=SalesOrderItem::where('tenant_id',$order->tenant_id)->where('sales_order_id',$order->id)->whereKey($line['sales_order_item_id'])->lockForUpdate()->firstOrFail();$remaining=Decimal::sub((string)$item->delivered_quantity,(string)$item->invoiced_quantity);if(Decimal::compare((string)$line['quantity'],$remaining)>0)throw ValidationException::withMessages(['quantity'=>['Cannot invoice more than delivered quantity.']]);$calcLine=$calc->line(['quantity'=>$line['quantity'],'unit_price'=>$item->unit_price,'discount_rate'=>$item->discount_rate,'tax_rate'=>$item->tax_rate]);$lines[]=$calcLine;$source[]=['item'=>$item,'quantity'=>$calcLine['quantity']];}$totals=$calc->totals($lines);$rate=(string)$order->exchange_rate;$invoice=SalesInvoice::create([...$totals,'tenant_id'=>$order->tenant_id,'company_id'=>$order->company_id,'branch_id'=>$order->branch_id,'currency_id'=>$order->currency_id,'exchange_rate'=>$rate,'base_total'=>Decimal::mul((string)$totals['total'],$rate),'customer_id'=>$order->customer_id,'sales_order_id'=>$order->id,'number'=>$numbers->next($order->tenant_id,'invoice'),'state'=>'issued']);foreach($source as $k=>$s){SalesInvoiceItem::create(['tenant_id'=>$order->tenant_id,'invoice_id'=>$invoice->id,'sales_order_item_id'=>$s['item']->id,'variant_id'=>$s['item']->variant_id,'quantity'=>$s['quantity'],'unit_price'=>$lines[$k]['unit_price'],'discount_amount'=>$lines[$k]['discount_amount'],'tax_amount'=>$lines[$k]['tax_amount'],'line_total'=>$lines[$k]['line_total']]);$s['item']->update(['invoiced_quantity'=>Decimal::add((string)$s['item']->invoiced_quantity,$s['quantity'])]);}return $invoice->load('items');});event(new \App\Events\InvoiceIssuedForAccounting($invoice->tenant_id,$invoice->id,$invoice->customer_id,(string)$invoice->total));return response()->json(['data'=>$invoice],201);} public function print(SalesInvoice $invoice){abort_unless($invoice->tenant_id===app(TenantContext::class)->id(),404);abort_unless(app(AuthorizationService::class)->allows(request()->user(),$invoice->tenant_id,'sales.view',$invoice->company_id,$invoice->branch_id),403);return response()->view('sales.invoice',compact('invoice'));} }
